<template><div class="page"><div class="section-title"><div><h2>集群观测</h2><span class="muted">只读查看 autoops-test namespace</span></div><n-button type="primary" @click="load">刷新</n-button></div><n-tabs type="line" animated><n-tab-pane name="pods" tab="Pods"><n-data-table :columns="podColumns" :data="pods" :loading="loading"/></n-tab-pane><n-tab-pane name="deployments" tab="Deployments"><n-data-table :columns="deploymentColumns" :data="deployments" :loading="loading"/></n-tab-pane><n-tab-pane name="events" tab="Events"><n-data-table :columns="eventColumns" :data="events" :loading="loading"/></n-tab-pane></n-tabs><n-drawer v-model:show="showLogs" :width="720" title="Pod Logs"><n-drawer-content><div v-if="logError" class="muted">{{logError}}</div><pre v-else class="log-window">{{logs}}</pre></n-drawer-content></n-drawer></div></template>
<script setup>import {h,ref,onMounted} from 'vue';import {clusterApi} from '@/api';const pods=ref([]),deployments=ref([]),events=ref([]),loading=ref(false),showLogs=ref(false),logs=ref(''),logError=ref('');const podColumns=[{title:'Pod',key:'name'},{title:'Status',key:'status'},{title:'Ready',key:'ready',render:r=>r.ready?'是':'否'},{title:'Restarts',key:'restarts'},{title:'Reason',key:'reason'},{title:'操作',key:'action',render:r=>h('button',{class:'link-button',onClick:()=>openLogs(r.name)},'查看日志')}];const deploymentColumns=[{title:'Deployment',key:'name'},{title:'Replicas',key:'replicas'},{title:'Available',key:'available'},{title:'Updated',key:'updated'},{title:'健康',key:'ready',render:r=>r.ready?'Healthy':'异常'}];const eventColumns=[{title:'Type',key:'type'},{title:'Reason',key:'reason'},{title:'Object',key:'object'},{title:'Message',key:'message'},{title:'Timestamp',key:'timestamp'}];async function load(){loading.value=true;try{const [p,d,e]=await Promise.all([clusterApi.pods(),clusterApi.deployments(),clusterApi.events()]);pods.value=p.data||[];deployments.value=d.data||[];events.value=e.data||[]}finally{loading.value=false}}async function openLogs(pod){showLogs.value=true;logs.value='Loading...';logError.value='';try{const r=await clusterApi.logs(pod,{tail_lines:200});logs.value=r.data?.logs||''}catch(e){logError.value=e.message;logs.value=''}}onMounted(load)</script>
